body { font-family: system-ui, sans-serif; background: #eaf2fb; padding: 16px; }
.quiz { max-width: 420px; margin: 0 auto; background: white; padding: 20px; border-radius: 12px; }
.choice { display: block; width: 100%; margin: 8px 0; padding: 10px; border-radius: 8px; border: 1px solid #0b6fd6; background: white; cursor: pointer; }
.choice.correct { background: #12936b; color: white; }
.choice.wrong { background: #d64545; color: white; }

const questions = [
  { text: "2 + 2 = ?", choices: ["3", "4", "5"], answer: "4" },
  { text: "Thủ đô của Việt Nam?", choices: ["Hà Nội", "Huế", "Đà Nẵng"], answer: "Hà Nội" },
];
let current = 0;
let score = 0;

const questionEl = document.getElementById("question");
const choicesEl = document.getElementById("choices");
const scoreEl = document.getElementById("score");

function showQuestion() {
  const q = questions[current];
  questionEl.textContent = q.text;
  choicesEl.replaceChildren();
  for (const choice of q.choices) {
    const btn = document.createElement("button");
    btn.className = "choice";
    btn.textContent = choice;
    choicesEl.appendChild(btn);
  }
}

choicesEl.addEventListener("click", (event) => {
  const btn = event.target.closest(".choice");
  if (!btn) return;
  if (btn.textContent === questions[current].answer) {
    score++;
    scoreEl.textContent = score;
  }
  current = (current + 1) % questions.length;
  showQuestion();
});

showQuestion();

